import {componentDefaults} from './scene-components.js';
import {validReplica,validNetworkRPC,interpolateReplica} from './network-state.js';
import {parseGameJson} from './game-json.js';
import {validValue} from './blueprint-model.js';
export class NetworkWorld{
 constructor(hooks={}){this.hooks=hooks;this.replicas=new Map();this.remote=new Map();this.stamps=new Map();this.events=[];this.elapsed=0;this.status='offline';this.generation=0;this.sequence=-1;this.resume='';this.peer='';this.authority=false;this.error='';this.disposed=false;}
 register(object){for(const c of object.components||[]){if(c.type==='NetworkReplica'&&c.properties?.enabled!==false){const p={...componentDefaults(c.type),...c.properties},id=p.networkId||object.id;if(this.replicas.has(id)&&this.replicas.get(id).object!==object)throw Error('네트워크 ID가 중복돼요: '+id);this.replicas.set(id,{object,component:c});}if(c.type==='NetworkSession'&&c.properties?.enabled!==false&&c.properties.endpoint){if(this.owner&&this.owner!==object)throw Error('네트워크 세션은 월드마다 하나예요.');const p={...componentDefaults(c.type),...c.properties};this.connect(object,p.endpoint,p.accessKey,p.authority);}}}
 connect(owner,endpoint,key,authority){
  if(this.disposed)throw Error('종료된 네트워크 월드예요.');const url=new URL(endpoint);if(!['ws:','wss:'].includes(url.protocol)||url.username||url.password||typeof key!=='string'||key.length>1000||typeof authority!=='boolean')throw Error('네트워크 주소·접속 키를 확인하세요.');
  const old=this.config;if(!old||old.endpoint!==endpoint||old.authority!==authority||old.key!==key)this.resume='';this.disconnect(false);this.config={endpoint,key,authority};this.owner=owner;this.authority=authority;this.sequence=-1;this.peer='';this.remote.clear();this.stamps.clear();for(const row of this.replicas.values()){const p={...componentDefaults('NetworkReplica'),...row.component.properties};row.object.gameplayDebug={...row.object.gameplayDebug,networkReplica:{owner:p.ownerPeer||'host',peer:'',authority:authority&&(p.ownerPeer||'host')==='host'}};}this.open();
 }
 open(){
  const generation=++this.generation,url=new URL(this.config.endpoint);url.searchParams.set('key',this.config.key);url.searchParams.set('role',this.authority?'host':'client');if(this.resume)url.searchParams.set('resume',this.resume);
  const Socket=this.hooks.WebSocket||globalThis.WebSocket;if(!Socket)throw Error('이 실행 환경에 WebSocket이 없어요.');const socket=new Socket(url.href);this.socket=socket;this.status='connecting';this.publish();
  this.timeout=setTimeout(()=>socket.close(),5000);
  socket.onmessage=event=>{if(this.generation!==generation)return;try{const packet=JSON.parse(String(event.data));if(packet.type==='welcome'){
    if(typeof packet.peer!=='string'||typeof packet.resume!=='string'||!Array.isArray(packet.states)||packet.states.some(s=>!validReplica(s))||!Number.isSafeInteger(packet.sequence))throw Error('네트워크 초기 상태 오류');this.peer=packet.peer;this.resume=packet.resume;this.sequence=packet.sequence;this.status=packet.chunks?'synchronizing':'connected';this.error='';this.retries=0;this.stamps.clear();this.sentOwners=new Map();for(const row of packet.states)this.remote.set(row.id,row);this.publish();
   }else if(packet.type==='snapshot'){
    if(this.status!=='synchronizing'||!Array.isArray(packet.states)||packet.states.some(s=>!validReplica(s)))throw Error('초기 스냅샷 오류');for(const row of packet.states)this.remote.set(row.id,row);
   }else if(packet.type==='welcomeEnd'){
    if(this.status!=='synchronizing'||!Number.isSafeInteger(packet.sequence))throw Error('초기 스냅샷 종료 오류');clearTimeout(this.timeout);this.sequence=packet.sequence;this.status='connected';this.publish();
   }else if(packet.type==='state'){
    if(!Number.isSafeInteger(packet.sequence)||packet.sequence<=this.sequence)return;if(!Array.isArray(packet.states)||packet.states.some(s=>!validReplica(s)))throw Error('복제 상태 오류');this.sequence=packet.sequence;for(const row of packet.states)this.remote.set(row.id,row);
   }else if(packet.type==='rpc'){
    if(!validNetworkRPC(packet)||typeof packet.sender!=='string'||this.events.length>=1024)throw Error('RPC 수신 예산·형식 오류');this.events.push(packet);
   }else throw Error('네트워크 응답 종류 오류');
  }catch(e){this.error=e.message;socket.close(1008,'invalid response');}};
  socket.onerror=()=>{if(this.generation===generation)this.error='네트워크 연결 오류';};
  socket.onclose=()=>{if(this.generation!==generation)return;clearTimeout(this.timeout);this.status='disconnected';this.publish();this.retry=setTimeout(()=>{if(!this.disposed&&this.config&&generation===this.generation)this.open();},Math.min(5000,250*2**Math.min(5,this.retries=(this.retries||0)+1)));};
 }
 publish(){const prior=this.owner?.gameplayDebug?.network;if(prior&&prior.status===this.status&&prior.peer===this.peer&&prior.authority===this.authority&&prior.sequence===this.sequence&&prior.replicas===this.replicas.size&&prior.error===this.error&&prior.lastRPC===(this.lastRPC||null))return;if(this.owner)this.owner.gameplayDebug={...this.owner.gameplayDebug,network:{status:this.status,peer:this.peer,authority:this.authority,sequence:this.sequence,replicas:this.replicas.size,error:this.error,lastRPC:this.lastRPC||null}};}
 send(packet){if(this.status!=='connected'||this.socket?.readyState!==1)throw Error('네트워크가 연결되지 않았어요.');if(this.socket.bufferedAmount>4194304)throw Error('네트워크 전송 대기 예산을 넘었어요.');this.socket.send(JSON.stringify(packet));}
 rpc(target,event,json,multicast){const row=this.replicas.get(target),packet={type:'rpc',target,event,args:parseGameJson(json),multicast};if(!row||!validNetworkRPC(packet))throw Error('RPC 대상·자료를 확인하세요.');if(multicast&&!this.authority)throw Error('멀티캐스트 RPC는 호스트만 호출해요.');this.send(packet);}
 async tick(delta,vm){
  if(!this.config)return;if(this.owner&&vm.object(this.owner.id)!==this.owner){this.disconnect();return;}this.elapsed+=delta;
  for(const [id,row] of this.replicas){const o=row.object;if(vm.object(o.id)!==o||o.destroying){this.replicas.delete(id);this.stamps.delete(id);continue;}const p={...componentDefaults('NetworkReplica'),...row.component.properties};if(!p.enabled)continue;const state=this.remote.get(id),owner=p.ownerPeer||'host';
   const authority=this.authority&&owner==='host'||!!this.peer&&(state?.owner||owner)===this.peer,prior=o.gameplayDebug?.networkReplica;if(!prior||prior.owner!==(state?.owner||owner)||prior.peer!==this.peer||prior.authority!==authority)o.gameplayDebug={...o.gameplayDebug,networkReplica:{owner:state?.owner||owner,peer:this.peer,authority}};
   if(state&&state.owner!==this.peer){const changed=interpolateReplica(o,{...(p.replicateTransform?{position:state.position,rotation:state.rotation,scale:state.scale}:{}),...(p.replicateVisibility?{visible:state.visible}:{})},delta,p.interpolation);if(p.replicateProperties&&state.properties&&row.appliedProperties!==state){const existing=o.nativeProperties||{},binding=vm.bindings.find(b=>b.self===o.id),definitions=binding?.root.native?.classes||[];for(const [name,value] of Object.entries(state.properties)){let definition=definitions.find(c=>c.name===o.nativeClass),property,depth=0;while(definition&&!property&&depth++<64){property=definition.properties.find(p=>p.name===name);definition=definitions.find(c=>c.name===definition.base);}if(property&&(property.array?Array.isArray(value)&&value.every(v=>validValue(property.type,v)):validValue(property.type,value)))existing[name]=structuredClone(value);}o.nativeProperties=existing;row.appliedProperties=state;}if(changed)await this.hooks.update?.(o);}
  }
  if(this.status==='connected'&&this.elapsed>=.05){this.elapsed=0;const rows=[];
   for(const [id,row] of this.replicas){const o=row.object,p={...componentDefaults('NetworkReplica'),...row.component.properties},owner=this.authority?p.ownerPeer||'host':this.remote.get(id)?.owner;if(!p.enabled||!this.authority&&owner!==this.peer||this.authority&&owner!=='host'&&this.sentOwners?.get(id)===owner)continue;const state={id,owner,...(p.replicateTransform?{position:o.position,rotation:o.rotation,scale:o.scale}:{}),...(p.replicateVisibility?{visible:o.visible!==false}:{}),...(p.replicateProperties?{properties:o.nativeProperties||{}}:{})};if(!validReplica(state)){this.error='복제 속성 크기·값을 확인하세요: '+id;continue;}const stamp=JSON.stringify(state);if(this.stamps.get(id)!==stamp){rows.push(state);this.stamps.set(id,stamp);this.sentOwners??=new Map();this.sentOwners.set(id,owner);}}
   if(rows.length){try{this.send({type:'state',rows});}catch(e){this.stamps.clear();this.sentOwners?.clear();this.error=e.message;}}
  }
  for(const event of this.events.splice(0)){const row=this.replicas.get(event.target);if(!row)continue;const p={...componentDefaults('NetworkReplica'),...row.component.properties};if(!p.rpcEvents.split(',').map(s=>s.trim()).includes(event.event))continue;this.lastRPC={target:row.object.id,event:event.event,sender:event.sender,args:event.args};for(const b of vm.bindings.filter(b=>b.self===row.object.id))await vm.custom(b,p.rpcHandler,{event:event.event,sender:event.sender,json:JSON.stringify(event.args)});}
  this.publish();
 }
 operation(key,args,b,vm){if(!key.startsWith('net'))return;const object=vm.object(args.target??b.self);if(!object)throw Error('네트워크 대상이 없어요.');if(key==='netConnect'){this.connect(object,args.endpoint,args.accessKey,args.authority);return {};}if(key==='netDisconnect'){this.disconnect();return {};}if(key==='netInfo'){const data=this.owner?.gameplayDebug?.network||{status:'offline'};object.gameplayDebug={...object.gameplayDebug,network:data};return {return:JSON.stringify(data)};}if(key==='netAuthority'){const authority=object.gameplayDebug?.networkReplica?.authority??!this.config;object.gameplayDebug={...object.gameplayDebug,networkReplica:{...object.gameplayDebug?.networkReplica,authority}};return {return:authority};}const row=[...this.replicas].find(([,r])=>r.object===object);if(!row)throw Error('Network Replica 컴포넌트가 필요해요.');if(key==='netRPC'){this.rpc(row[0],args.event,args.json,args.multicast);return {};}if(key==='netSetOwner'){if(!this.authority||typeof args.peer!=='string'||!args.peer||args.peer.length>160)throw Error('호스트 소유권 지정 오류');row[1].component.properties={...row[1].component.properties,ownerPeer:args.peer};this.stamps.delete(row[0]);return {};}throw Error('네트워크 명령 오류');}
 disconnect(clear=true){this.generation++;clearTimeout(this.retry);clearTimeout(this.timeout);this.socket?.close();this.socket=null;this.status='offline';this.events=[];if(clear){this.config=null;this.remote.clear();this.stamps.clear();this.peer='';this.lastRPC=null;for(const row of this.replicas.values())row.object.gameplayDebug={...row.object.gameplayDebug,networkReplica:{owner:'',peer:'',authority:true}};}this.publish();}
 dispose(){this.disconnect();this.disposed=true;this.replicas.clear();this.owner=null;}
}
